func (q *Queries) WithdrawOffer(ctx context.Context, arg WithdrawOfferParams) (Offer, error) {
	row := q.db.QueryRow(ctx, withdrawOffer, arg.ID, arg.LenderOrg)
	var i Offer
	err := row.Scan(
		&i.ID,
		&i.ApplicationID,
		&i.LenderOrganizationID,
		&i.CreatedByUserID,
		&i.Status,
		&i.RejectReason,
		&i.RejectComment,
		&i.Amount,
		&i.Currency,
		&i.InterestRateAnnual,
		&i.FeePercent,
		&i.RepaymentSchedule,
		&i.Collateral,
		&i.AdditionalTerms,
		&i.ValidUntil,
		&i.CreatedAt,
		&i.DecidedAt,
	)
	return i, err
}
